<?php
namespace Ishep\Services;use DomainException;
final class PortalStatus
{private const OPPORTUNITY=['draft'=>['published'],'published'=>['closed'],'closed'=>['archived'],'archived'=>[]];private const CAREER=['draft'=>['submitted'],'submitted'=>['under_review','withdrawn'],'under_review'=>['shortlisted','unsuccessful','withdrawn'],'shortlisted'=>['hired','unsuccessful','withdrawn'],'unsuccessful'=>[],'withdrawn'=>[],'hired'=>[]];private const BURSARY=['draft'=>['submitted'],'submitted'=>['under_review','withdrawn'],'under_review'=>['shortlisted','approved','unsuccessful','withdrawn'],'shortlisted'=>['approved','unsuccessful','withdrawn'],'approved'=>[],'unsuccessful'=>[],'withdrawn'=>[]];public function assertOpportunity(string $from,string $to):void{$this->assert(self::OPPORTUNITY,$from,$to);}public function assertApplication(string $domain,string $from,string $to):void{$this->assert($domain==='career'?self::CAREER:self::BURSARY,$from,$to);}private function assert(array $rules,string $from,string $to):void{if(!in_array($to,$rules[$from]??[],true))throw new DomainException('This status transition is not allowed.');}}
